// js_unit.js -- unit tests for the Cave Survey Core library.
//
// The Core is pure ECMAScript, so the same tests run two ways:
//
//   inside CaveCAD's own engine (authoritative -- the engine the add-on
//   really runs in):
//     /Applications/CaveCAD.app/Contents/MacOS/CaveCAD \
//         -no-dock-icon -no-gui -allow-multiple-instances \
//         -autostart tests/js_unit.js "$PWD"
//
//   under node (developer convenience):
//     node tests/js_unit.js
//
// Prints "### UNIT OK <n> assertions" on success; any failure prints
// "### UNIT FAIL" plus details and (in QCAD) leaves that marker for
// run_all.sh to spot.

// ---------------------------------------------------------------------
// Environment shim: repo root, file reading, and an include() that
// resolves "scripts/..." paths against the repo checkout instead of
// QCAD's installed script folders.
// ---------------------------------------------------------------------

var IS_NODE = (typeof process !== "undefined" && process.versions &&
    process.versions.node !== undefined);

var repoRoot;
var readTextFile;
var readBinaryFile;   // file -> latin1 string: charCodeAt(i) === byte i

if (IS_NODE) {
    var nodeFs = require("fs");
    var nodePath = require("path");
    repoRoot = nodePath.resolve(__dirname, "..");
    readTextFile = function(path) {
        return nodeFs.readFileSync(path, "utf8");
    };
    readBinaryFile = function(path) {
        return nodeFs.readFileSync(path, "latin1");
    };
} else {
    var args = RSettings.getOriginalArguments();
    repoRoot = args[args.length - 1];
    readTextFile = function(path) {
        var file = new QFile(path);
        if (!file.open(QIODevice.ReadOnly | QIODevice.Text)) {
            throw new Error("cannot open " + path);
        }
        var stream = new QTextStream(file);
        var content = stream.readAll();
        file.close();
        return content;
    };
    readBinaryFile = function(path) {
        var file = new QFile(path);
        if (!file.open(QIODevice.ReadOnly)) {
            throw new Error("cannot open " + path);
        }
        var stream = new QTextStream(file);
        // Latin1 maps all 256 byte values 1:1 onto code points, so the
        // string IS the bytes (probed 2026-08-27; see CsContour.js).
        stream.setEncoding(QStringConverter.Latin1);
        var content = stream.readAll();
        file.close();
        return String(content);
    };
}

// Some builds' -autostart engines don't preload library.js's isNull --
// but this build is worse: it preloads a NATIVE isNull (typeof isNull
// is already "function", so the old `typeof isNull === "undefined"`
// guard never fired) that does not know about Qt6's __PROXY__
// indirection at all. Measured 2026-09-12 on a brand-new RDocument
// with no custom blocks: doc.queryBlock("anything-that-does-not-
// exist") answers an RBlock wrapper whose __PROXY__ target's own
// isNullWrapper() correctly says true, but the native global isNull()
// never looks at __PROXY__ and answers false -- "this block exists"
// for a block that was never created. CsShapeLine's missing-block
// import path (buildDecor) depends on isNull(doc.queryBlock(...))
// telling the truth, so it silently never ran ensureBlock. This
// ALWAYS installs library.js's own algorithm (recursing through
// __PROXY__, then isNullWrapper()/data()+isNull()) over whatever is
// already bound, native or not -- the one place this suite's tests
// can be sure they are exercising the same logic library.js ships.
isNull = function(v) {
    if (v === undefined || v === null) {
        return true;
    }
    try {
        if (RSettings.getQtVersion() >= 0x060000 &&
                v.hasOwnProperty("__PROXY__")) {
            return isNull(v.__PROXY__);
        }
    } catch (eProxy) {
    }
    try {
        if (typeof v.isNullWrapper === "function" &&
                v.isNullWrapper() === true) {
            return true;
        }
    } catch (eWrap) {
    }
    try {
        if (typeof v.data === "function" && typeof v.isNull === "function" &&
                v.isNull() === true) {
            return true;
        }
    } catch (ePtr) {
    }
    return false;
};
// Same reason as isNull above -- the hookup tests further down build
// real RDocuments, and this build's -autostart entry point does not
// always preload library.js's own copy.
if (typeof createSpatialIndex === "undefined") {
    createSpatialIndex = function() {
        return new RSpatialIndexNavel();
    };
}

var loaded = {};
// Core files include() each other with scripts/-rooted paths; loading
// here goes through the same door so the graph stays honest.
function loadRepoScript(scriptPath) {
    if (loaded[scriptPath]) {
        return;
    }
    loaded[scriptPath] = true;
    var source = readTextFile(repoRoot + "/" + scriptPath);
    // Strip include() lines -- we load dependencies explicitly below,
    // and QCAD's own include() would look in the wrong place.
    source = source.replace(/^\s*include\(.*\);\s*$/mg, "");
    // Indirect eval, so definitions land in the GLOBAL scope in both
    // engines rather than in this function's scope.
    (0, eval)(source);
}

