    ok(CsLayers.CTRL_RAW === "CTRL-RAW", "the as-surveyed ghost layer is CTRL-RAW");
    ok(CsLayers.DEFAULTS["CTRL-RAW"][1] === "DASHED",
        "CTRL-RAW is dashed -- it is not the survey, it is where the survey was");
