// ---------------------------------------------------------------------
// Start date field -- ExpeditionPlanner.startDateText/setStartDateText,
// the only readers/writers of the Qt QDateEdit, against a fake widget.
// ---------------------------------------------------------------------

if (typeof EAction === "undefined") {
    EAction = function() {};
    EAction.prototype.beginEvent = function() {};
    EAction.prototype.terminate = function() {};
    EAction.handleUserMessage = function() {};
}
loadRepoScript("scripts/CaveSurvey/ExpeditionPlanner/ExpeditionPlanner.js");
ok(typeof ExpeditionPlanner.startDateText === "function" &&
    typeof ExpeditionPlanner.setStartDateText === "function", "qd: accessors exist");
if (typeof ExpeditionPlanner.startDateText === "function") {
    (function() {
        // Behaves as the live QDateEdit: text shows the date;
        // setProperty("date", iso) moves it. No unset state any more.
        var fake = { shown: "2026-09-29", sets: [],
            property: function(name) { return name === "text" ? this.shown : undefined; },
            setProperty: function(name, v) {
                this.sets.push(name + "=" + v);
                if (name === "date") { this.shown = v; }
            } };
        var realChild = ExpeditionPlanner.child;
        var realToday = ExpeditionPlanner.todayIso;
        ExpeditionPlanner.todayIso = function() { return "2026-09-29"; };
        var present = true;
        ExpeditionPlanner.child = function(name) {
            return (present && name === "ExpeditionPlannerCalloutStart") ? fake : null;
        };
        try {
            var read = function(shown) { fake.shown = shown; return ExpeditionPlanner.startDateText(); };
            eqs(read("2026-10-03"), "2026-10-03", "qd: a valid date reads back");
            eqs(read(" 2026-10-03 "), "2026-10-03", "qd: surrounding space trimmed");
            eqs(read("Pick a date"), "", "dd: old placeholder text is junk, reads empty");
            eqs(read("1970-01-01"), "1970-01-01", "dd: 1970-01-01 is now just a valid date");
            eqs(read("2026-02-30"), "", "qd: an impossible day is unset");
            eqs(read("2026-2-3"), "", "qd: unpadded text is unset");
            eqs(read("junk"), "", "qd: junk is unset");
            eqs(read(""), "", "qd: empty is unset");
            fake.shown = undefined;
            eqs(ExpeditionPlanner.startDateText(), "", "qd: undefined text is unset");

            fake.sets = [];
            ExpeditionPlanner.setStartDateText("2027-01-15");
            eqs(fake.sets.join(","), "date=2027-01-15", "qd: set writes the date property");
            eqs(ExpeditionPlanner.startDateText(), "2027-01-15", "qd: set then read round-trips");
            fake.sets = [];
            ExpeditionPlanner.setStartDateText("");
            eqs(fake.sets.join(","), "date=2026-09-29", "dd: empty writes today");
            eqs(ExpeditionPlanner.startDateText(), "2026-09-29", "dd: empty reads back as today");
            fake.sets = [];
            ExpeditionPlanner.setStartDateText("3/10/2026");
            eqs(fake.sets.join(","), "date=2026-09-29", "dd: junk text writes today");
            fake.sets = [];
            ExpeditionPlanner.setStartDateText(null);
            eqs(fake.sets.join(","), "date=2026-09-29", "dd: null writes today");
            fake.sets = [];
            ExpeditionPlanner.setStartDateText("2026-13-01");
            eqs(fake.sets.join(","), "date=2026-09-29", "dd: an impossible month writes today");
            fake.sets = [];
            ExpeditionPlanner.setStartDateText("1970-01-01");
            eqs(fake.sets.join(","), "date=1970-01-01", "dd: 1970-01-01 is written as is");

            present = false;
            eqs(ExpeditionPlanner.startDateText(), "", "qd: no widget reads empty");
            fake.sets = [];
            ExpeditionPlanner.setStartDateText("2026-10-03");
            eqs(fake.sets.length, 0, "qd: no widget, nothing written");
        } finally {
            ExpeditionPlanner.child = realChild;
            ExpeditionPlanner.todayIso = realToday;
        }
    })();
}

// dd: todayIso is the local date, zero padded.
ok(/^\d{4}-\d{2}-\d{2}$/.test(ExpeditionPlanner.todayIso()) &&
    csStoreDateOk(ExpeditionPlanner.todayIso()), "dd: todayIso is a valid yyyy-mm-dd");
ok(ExpeditionPlanner.START_DATE_UNSET === undefined, "dd: the unset placeholder is gone");
(function() {
    var ui = readTextFile(repoRoot + "/scripts/CaveSurvey/ExpeditionPlanner/ExpeditionPlannerDate.ui");
    ok(ui.indexOf("#e8811a") >= 0, "dd: .ui carries the orange accent");
    ok(ui.indexOf("qt_calendar_navigationbar") >= 0, "dd: .ui styles the calendar navigation bar");
    ok(ui.indexOf("specialValueText") < 0, "dd: .ui has no specialValueText");
})();

// A start date typed any other way than yyyy-mm-dd is a gap Build names.
var qdMissTrip = function(date) {
    return { startDate: date, days: [ { entry: "08:00", workHours: 6, night: "out" } ] };
};
var qdMissContacts = { topName: "T", topPhone: "1", escalation: "E" };
var qdMissRoster = [ { name: "A" } ];
var qdMissPlan = { stops: [ { station: "A1" } ] };
ok(CsCalloutCard.missingAll(qdMissTrip("2026-2-3"), qdMissPlan, qdMissContacts,
    qdMissRoster, true).indexOf("start date") >= 0, "qd: 2026-2-3 is a missing start date");
ok(CsCalloutCard.missingAll(qdMissTrip("3/10/2026"), qdMissPlan, qdMissContacts,
    qdMissRoster, true).indexOf("start date") >= 0, "qd: 3/10/2026 is a missing start date");
ok(CsCalloutCard.missingAll(CsStationStore.cleanTrip(qdMissTrip("2026-2-3")), qdMissPlan,
    qdMissContacts, qdMissRoster, true).indexOf("start date") >= 0,
    "qd: 2026-2-3 through cleanTrip is missing");
ok(CsCalloutCard.missingAll(CsStationStore.cleanTrip(qdMissTrip("3/10/2026")), qdMissPlan,
    qdMissContacts, qdMissRoster, true).indexOf("start date") >= 0,
    "qd: 3/10/2026 through cleanTrip is missing");
ok(CsCalloutCard.missingAll(CsStationStore.cleanTrip(qdMissTrip("")), qdMissPlan,
    qdMissContacts, qdMissRoster, true).indexOf("start date") >= 0,
    "qd: an unset field (\"\") is a missing start date");
ok(CsCalloutCard.missingAll(CsStationStore.cleanTrip(qdMissTrip("2026-10-03")), qdMissPlan,
    qdMissContacts, qdMissRoster, true).indexOf("start date") < 0,
    "qd: 2026-10-03 is not missing");


// ---------------------------------------------------------------------
// Dock build must never re-enter itself (0.9.194.0 startup hang)
// ---------------------------------------------------------------------

if (typeof ExpeditionPlanner !== "undefined" &&
        typeof ExpeditionPlanner.ensureDock === "function") {
    (function() {
        var realBuild = ExpeditionPlanner.buildDock;
        var realDock = csExpeditionPlannerDock;
        var builds = 0;
        var inner = "unset";
        var fakeDock = { findChild: function() { return null; } };
        // The bug: a build-time child()/setStartDateText lookup called
        // ensureDock() again while the global was still unset, so the
        // dock was built again, forever.
        ExpeditionPlanner.buildDock = function() {
            builds++;
            if (builds > 5) {
                return fakeDock;
            }
            inner = ExpeditionPlanner.child("ExpeditionPlannerCalloutStart");
            return fakeDock;
        };
        csExpeditionPlannerDock = null;
        try {
            var got = ExpeditionPlanner.ensureDock();
            eqs(builds, 1, "dd2: a lookup during the build does not rebuild the dock");
            ok(inner === null, "dd2: a lookup during the build answers null");
            ok(got === fakeDock, "dd2: the built dock is returned");
            eqs(ExpeditionPlanner.building, false, "dd2: the build flag is cleared");
            ExpeditionPlanner.ensureDock();
            eqs(builds, 1, "dd2: a built dock is reused");
        } finally {
            ExpeditionPlanner.buildDock = realBuild;
            csExpeditionPlannerDock = realDock;
            ExpeditionPlanner.building = false;
        }
        // writeStartDate takes the widget itself, so the build needs no lookup.
        var wrote = [];
        var w = { setProperty: function(n, v) { wrote.push(n + "=" + v); } };
        var realToday = ExpeditionPlanner.todayIso;
        ExpeditionPlanner.todayIso = function() { return "2026-09-29"; };
        try {
            ExpeditionPlanner.writeStartDate(w, "");
            ExpeditionPlanner.writeStartDate(w, "2026-10-03");
            ExpeditionPlanner.writeStartDate(null, "2026-10-03");
        } finally {
            ExpeditionPlanner.todayIso = realToday;
        }
        eqs(wrote.join("|"), "date=2026-09-29|date=2026-10-03",
            "dd2: writeStartDate writes today for blank and the date otherwise, and ignores a null widget");
    })();
}

// ---------------------------------------------------------------------
// Start date Today button
// ---------------------------------------------------------------------

if (typeof ExpeditionPlanner !== "undefined" &&
        typeof ExpeditionPlanner.startDateToday === "function") {
    (function() {
        var wrote = [];
        var fake = { setProperty: function(n, v) { wrote.push(n + "=" + v); } };
        var realChild = ExpeditionPlanner.child;
        var realToday = ExpeditionPlanner.todayIso;
        ExpeditionPlanner.todayIso = function() { return "2026-09-29"; };
        ExpeditionPlanner.child = function(name) {
            return name === "ExpeditionPlannerCalloutStart" ? fake : null;
        };
        try {
            ExpeditionPlanner.startDateToday();
        } finally {
            ExpeditionPlanner.child = realChild;
            ExpeditionPlanner.todayIso = realToday;
        }
        eqs(wrote.join("|"), "date=2026-09-29", "today: the Today button writes today's date into the field");
    })();
} else {
    ok(false, "today: ExpeditionPlanner.startDateToday exists");
}

// ---------------------------------------------------------------------
// Teams in the trip store.
// ---------------------------------------------------------------------

(function() {
    var rt = function(trip) {
        var st = CsStationStore.empty();
        st.settings.trip = trip;
        return CsStationStore.parse(CsStationStore.serialize(st)).store.settings.trip;
    };
    var tmE = CsStationStore.emptyTrip();
    ok(typeof CsStationStore.cleanTeam === "function" &&
        typeof CsStationStore.cleanDays === "function", "tm store: cleanTeam and cleanDays exist");
    eqs(JSON.stringify(tmE.teams), "[]", "tm store: emptyTrip has teams []");
    var tmTrip = { startDate: "2026-10-03", weatherPlace: "X",
        party: [{ id: "p1", name: "Ana" }],
        days: [{ entry: "8:00", workHours: 4, night: "camp" }],
        teams: [
            { id: "t1", name: "  Alpha ", goal: "  Survey B ", dayOffset: 2,
              members: [{ id: "a", name: "Ana", medical: "x" }, { id: "", name: "  " },
                  { id: "a", name: "Other" }, { id: "b", name: " ana " }, { name: "Bo" }],
              stops: [" B20 ", "", "D8", "B20", "  "],
              days: [{ entry: "9:30", workHours: 5, night: "bogus" },
                  { entry: "25:00", workHours: 5 }, { entry: "08:00", workHours: -1 }],
              packing: "  First aid  ", medical: "x", phone: "y" },
            { id: "t2", name: "   ", goal: null, dayOffset: -3, members: "no", stops: null,
              days: null, packing: null } ] };
    var tmBack = rt(tmTrip);
    eqs(tmBack.teams.length, 2, "tm store: two teams round trip");
    var a = tmBack.teams[0], b = tmBack.teams[1];
    eqs(a.id, "t1", "tm store: id kept");
    eqs(a.name, "Alpha", "tm store: name trimmed");
    eqs(a.goal, "Survey B", "tm store: goal trimmed");
    eqs(a.packing, "First aid", "tm store: packing trimmed");
    eqs(a.dayOffset, 2, "tm store: dayOffset kept");
    eqs(JSON.stringify(a.members), JSON.stringify([{ id: "a", name: "Ana" }, { id: "", name: "Bo" }]),
        "tm store: members cleaned, nameless and duplicates dropped, unknown fields gone");
    eqs(JSON.stringify(a.stops), JSON.stringify(["B20", "D8"]), "tm store: stops trimmed, deduped, ordered");
    eqs(JSON.stringify(a.days), JSON.stringify([{ entry: "09:30", workHours: 5, night: "out" }]),
        "tm store: team days cleaned like trip days");
    eqs(b.name, "Team 2", "tm store: blank name becomes Team 2 by position");
    eqs(b.goal, "", "tm store: null goal is blank");
    eqs(b.dayOffset, 0, "tm store: negative dayOffset is 0");
    eqs(b.members.length + b.stops.length + b.days.length, 0, "tm store: bad lists are empty");
    eqs(b.packing, "", "tm store: null packing is blank");
    eqs(rt({ teams: [{ dayOffset: "3" }] }).teams[0].dayOffset, 0, "tm store: text dayOffset is 0");
    eqs(rt({ teams: [{ dayOffset: 1.5 }] }).teams[0].dayOffset, 0, "tm store: fractional dayOffset is 0");
    var nine = [];
    for (var i = 0; i < 9; i++) { nine.push({ name: "T" + i }); }
    eqs(rt({ teams: nine }).teams.length, 8, "tm store: at most 8 teams");
    eqs(rt({ teams: [null, 5, { name: "Z" }] }).teams[0].name, "Z", "tm store: non-object teams skipped");
    var txt = CsStationStore.serialize((function() { var s = CsStationStore.empty();
        s.settings.trip = tmTrip; return s; })());
    ok(txt.indexOf("medical") < 0 && txt.indexOf("phone") < 0, "tm store: medical/phone never serialised");
    var tmLegacy = rt({ days: [{ entry: "08:00", workHours: 3, night: "out" }], party: [{ id: "p", name: "P" }] });
    eqs(tmLegacy.teams.length, 0, "tm store: legacy-only trip keeps teams []");
    eqs(tmLegacy.days.length, 1, "tm store: legacy days kept");
    eqs(tmLegacy.days[0].entry, "08:00", "tm store: legacy day entry as before");
    eqs(tmLegacy.party.length, 1, "tm store: legacy party kept");
    eqs(rt(tmTrip).days[0].entry, "08:00", "tm store: trip day zero-padded");
})();

// ---------------------------------------------------------------------
// Teams engine (CsTeams)
// ---------------------------------------------------------------------
(function() {
    var day = function(entry, hrs, night) { return { entry: entry, workHours: hrs, night: night }; };
    var tm = function(name, off, members, days) {
        return { id: "id-" + name, name: name, goal: "", dayOffset: off, members: members,
            stops: [], days: days, packing: "" };
    };
    var b = CsTeams.blank("Deep");
    ok(CsUuid.isValid(b.id), "tm engine: blank has a uuid");
    eqs(JSON.stringify({ n: b.name, g: b.goal, o: b.dayOffset, m: b.members, s: b.stops, d: b.days, p: b.packing }),
        JSON.stringify({ n: "Deep", g: "", o: 0, m: [], s: [], d: [], p: "" }), "tm engine: blank shape");
    ok(CsTeams.blank("x").id !== CsTeams.blank("x").id, "tm engine: blank ids differ");

    var src = tm("A", 2, [{ id: "p1", name: "Pat" }], [day("08:00", 4, "out")]);
    src.stops = ["S1"]; src.packing = "rope";
    var cp = CsTeams.copyOf(src, "B");
    ok(cp.id !== src.id && CsUuid.isValid(cp.id), "tm engine: copyOf new id");
    eqs(cp.name, "B", "tm engine: copyOf name");
    eqs(cp.dayOffset, 2, "tm engine: copyOf keeps offset");
    eqs(cp.days.length, 1, "tm engine: copyOf keeps days");
    eqs(cp.days[0].entry, "08:00", "tm engine: copyOf day content");
    eqs(cp.members.length + cp.stops.length, 0, "tm engine: copyOf no members/stops");
    eqs(cp.packing, "", "tm engine: copyOf empty packing");
    cp.days[0].entry = "09:00";
    eqs(src.days[0].entry, "08:00", "tm engine: copyOf days are a deep copy");

    var lt = { startDate: "2026-10-03", days: [day("08:00", 4, "out")], teams: [] };
    var lp = [{ id: "p1", name: "Pat" }];
    var ltJson = JSON.stringify(lt), lpJson = JSON.stringify(lp);
    var fl = CsTeams.fromLegacy(lt, "rope", lp);
    eqs(fl.length, 1, "tm engine: fromLegacy one team");
    eqs(fl[0].name, "Team 1", "tm engine: fromLegacy name");
    eqs(fl[0].days.length, 1, "tm engine: fromLegacy days");
    eqs(fl[0].members[0].name, "Pat", "tm engine: fromLegacy party");
    eqs(fl[0].packing, "rope", "tm engine: fromLegacy packing");
    ok(CsUuid.isValid(fl[0].id), "tm engine: fromLegacy id");
    fl[0].days[0].entry = "10:00"; fl[0].members[0].name = "Zed";
    eqs(JSON.stringify(lt), ltJson, "tm engine: fromLegacy does not mutate trip");
    eqs(JSON.stringify(lp), lpJson, "tm engine: fromLegacy does not mutate party");
    var fe = CsTeams.fromLegacy({ startDate: "", days: [] }, "", []);
    eqs(fe.length, 1, "tm engine: fromLegacy empty -> one team");
    eqs(fe[0].name + "|" + fe[0].days.length + "|" + fe[0].members.length, "Team 1|0|0",
        "tm engine: fromLegacy empty team is empty");
    var have = [tm("Z", 0, [], [])];
    eqs(CsTeams.fromLegacy({ days: [day("08:00", 1, "out")], teams: have }, "x", []), have,
        "tm engine: fromLegacy keeps existing teams");

    var trip = { startDate: "2026-10-03" };
    eqs(CsTeams.dates(trip, tm("A", 0, [], [day("8:00", 1, "camp"), day("8:00", 1, "out")])).join(","),
        "2026-10-03,2026-10-04", "tm engine: dates");
    eqs(CsTeams.dates(trip, tm("A", 2, [], [day("8:00", 1, "camp"), day("8:00", 1, "out")])).join(","),
        "2026-10-05,2026-10-06", "tm engine: dates with offset");
    eqs(CsTeams.dates({ startDate: "2026-10-31" }, tm("A", 1, [], [day("8:00", 1, "out"), day("8:00", 1, "out")])).join(","),
        "2026-11-01,2026-11-02", "tm engine: dates cross a month");
    eqs(CsTeams.dates({ startDate: "" }, tm("A", 0, [], [day("8:00", 1, "out")])).join(","), "",
        "tm engine: dates empty for no start");
    eqs(CsTeams.dates({ startDate: "2026-02-31" }, tm("A", 0, [], [day("8:00", 1, "out")])).length, 0,
        "tm engine: dates empty for invalid start");

    // Same-day conflicts.
    var pat = { id: "p1", name: "Pat" };
    var one = day("08:00", 4, "out");
    var t1 = { startDate: "2026-10-03", teams: [
        tm("Alpha", 0, [pat], [one, one]), tm("Beta", 1, [pat], [one]) ] };
    var c1 = CsTeams.sameDayConflicts(t1);
    eqs(c1.length, 1, "tm engine: one overlapping day");
    eqs(c1[0].date + "|" + c1[0].person + "|" + c1[0].teams.join(","), "2026-10-04|Pat|Alpha,Beta",
        "tm engine: conflict shape");
    var t2 = { startDate: "2026-10-03", teams: [
        tm("Alpha", 0, [pat], [one]), tm("Beta", 1, [pat], [one]) ] };
    eqs(CsTeams.sameDayConflicts(t2).length, 0, "tm engine: same person, different dates: no warning");
    var t3 = { startDate: "2026-10-03", teams: [
        tm("A", 0, [pat], [one]), tm("B", 0, [pat], [one]), tm("C", 0, [pat], [one]) ] };
    var c3 = CsTeams.sameDayConflicts(t3);
    eqs(c3.length, 1, "tm engine: three teams, one entry");
    eqs(c3[0].teams.join(","), "A,B,C", "tm engine: three teams named in order");
    var t4 = { startDate: "2026-10-03", teams: [
        tm("A", 0, [{ id: "", name: "  PAT " }], [one]), tm("B", 0, [{ id: "", name: "pat" }], [one]) ] };
    eqs(CsTeams.sameDayConflicts(t4).length, 1, "tm engine: name match trimmed, case blind");
    var t5 = { startDate: "2026-10-03", teams: [
        tm("A", 0, [{ id: "p1", name: "Pat" }], [one]), tm("B", 0, [{ id: "p2", name: "Pat" }], [one]) ] };
    eqs(CsTeams.sameDayConflicts(t5).length, 0, "tm engine: different ids, same name: two people");
    var t6 = { startDate: "2026-10-03", teams: [
        tm("A", 0, [{ id: "p1", name: "Pat" }], [one]), tm("B", 0, [{ id: "", name: "pat" }], [one]) ] };
    var c6 = CsTeams.sameDayConflicts(t6);
    eqs(c6.length, 1, "tm engine: one team by id, another by name only, is a conflict");
    eqs(c6[0].teams.join(","), "A,B", "tm engine: alias conflict names both teams");
    var t7 = { startDate: "2026-10-03", teams: [
        tm("B", 0, [{ id: "", name: "pat" }], [one]), tm("A", 0, [{ id: "p1", name: "Pat" }], [one]) ] };
    eqs(CsTeams.sameDayConflicts(t7).length, 1, "tm engine: alias conflict, name-only team first");
    var t8 = { startDate: "2026-10-03", teams: [
        tm("A", 0, [{ id: "p1", name: "Pat" }, { id: "p2", name: "Al" }], [one, one]),
        tm("B", 1, [{ id: "p2", name: "Al" }, { id: "p1", name: "Pat" }], [one]),
        tm("C", 0, [{ id: "p2", name: "Al" }], [one]) ] };
    var c8 = CsTeams.sameDayConflicts(t8);
    eqs(c8.map(function(x) { return x.date + " " + x.person; }).join(","),
        "2026-10-03 Al,2026-10-04 Al,2026-10-04 Pat", "tm engine: sorted by date then person");
    eqs(CsTeams.sameDayConflicts({ startDate: "", teams: t8.teams }).length, 0, "tm engine: no start, no conflicts");
    eqs(CsTeams.sameDayConflicts({ startDate: "2026-10-03" }).length, 0, "tm engine: no teams, no conflicts");
    var t9 = { startDate: "2026-10-03", teams: [
        tm("Same", 0, [pat], [one]), tm("Same", 0, [pat], [one]) ] };
    eqs(CsTeams.sameDayConflicts(t9).length, 0, "tm engine: one team name twice is not two teams");

    // Windows.
    var plan = { stops: [{ station: "A3", steps: [], minutesIn: 90 }],
        totals: { minutesIn: 90, minutesWork: 20, minutesOut: 80 } };
    var w0 = CsTeams.windows(plan, trip, tm("A", 0, [], [day("08:00", 4, "out")]), 120);
    eqs(w0.rows[0].entry.date + " " + w0.rows[0].entry.time, "2026-10-03 08:00", "tm engine: windows day 1");
    eqs(w0.rows[0].callout.time, "16:50", "tm engine: windows callout");
    var w1 = CsTeams.windows(plan, trip, tm("A", 1, [], [day("08:00", 4, "out")]), 120);
    eqs(w1.rows[0].entry.date, "2026-10-04", "tm engine: windows offset 1 shifts entry");
    eqs(w1.rows[0].callout.date, "2026-10-04", "tm engine: windows offset 1 shifts callout");
    var wsame = CsCalloutCard.windows(plan, { startDate: "2026-10-04",
        days: [day("08:00", 4, "out")] }, 120);
    eqs(JSON.stringify(w1), JSON.stringify(wsame), "tm engine: windows equals card windows at shifted date");
    eqs(CsTeams.windows(plan, { startDate: "" }, tm("A", 1, [], [day("08:00", 4, "out")]), 120).rows.length, 0,
        "tm engine: windows empty for no start");

    // Callout strip.
    var mk = function(n, days) { return { team: n, rows: CsTeams.windows(plan, trip,
        tm(n, 0, [], days), 60).rows }; };
    var strip = CsTeams.calloutStrip([
        mk("Alpha", [day("08:00", 4, "out"), day("08:00", 4, "out")]),
        mk("Beta", [day("08:00", 4, "out")]) ]);
    eqs(strip.map(function(s) { return s.team + " " + s.stamp.date + " " + s.stamp.time; }).join(","),
        "Alpha 2026-10-03 15:50,Beta 2026-10-03 15:50,Alpha 2026-10-04 15:50",
        "tm engine: strip sorted by time, ties by team order");
    eqs(strip[0].kind, "callout", "tm engine: strip kind");
    var camp = CsTeams.calloutStrip([mk("Camp", [day("08:00", 4, "camp")]),
        mk("Beta", [day("09:00", 4, "out")])]);
    eqs(camp.length, 2, "tm engine: camp-only team: camp day contributes nothing besides the last day");
    var campOnly = CsTeams.calloutStrip([{ team: "Camp", rows: [
        { callout: null, endsOnSurface: false }] }]);
    eqs(campOnly.length, 0, "tm engine: camp-only team contributes nothing");
    eqs(CsTeams.calloutStrip([]).length, 0, "tm engine: empty strip");
    var plainArr = CsTeams.calloutStrip([w0.rows]);
    eqs(plainArr.length + plainArr[0].team, "1Team 1", "tm engine: strip accepts bare rows, default label");

    // missingAll.
    var full = { startDate: "2026-10-03", teams: [
        { id: "a", name: "Alpha", members: [pat], stops: ["S"], days: [one] },
        { id: "b", name: "Beta", members: [{ id: "", name: "Bo" }], stops: ["S"], days: [one] } ] };
    var contacts = { topName: "Top", topPhone: "555", escalation: "call" };
    var plans = [{ stops: [{}] }, { stops: [{}] }];
    eqs(CsTeams.missingAll(full, plans, contacts, [], true).join("|"), "", "tm engine: complete -> nothing missing");
    var mm = function(f) {
        var tt = JSON.parse(JSON.stringify(full)), cc = JSON.parse(JSON.stringify(contacts)),
            pp = JSON.parse(JSON.stringify(plans));
        var r = f(tt, cc, pp);
        return CsTeams.missingAll(tt, pp, cc, [], true).join("|");
    };
    eqs(mm(function(t) { t.startDate = ""; }), "start date", "tm engine: missing start alone");
    eqs(mm(function(t) { t.startDate = "2026-02-31"; }), "start date", "tm engine: invalid start");
    eqs(mm(function(t, c) { c.topName = "  "; }), "topside contact name", "tm engine: missing contact name (blank)");
    eqs(mm(function(t, c) { c.topPhone = ""; }), "contact phone", "tm engine: missing phone");
    eqs(mm(function(t, c) { c.escalation = " \t"; }), "the if-no-word escalation line",
        "tm engine: missing escalation (whitespace)");
    eqs(mm(function(t) { t.teams[1].name = "   "; }), "Team 2: a name", "tm engine: blank team name, default label");
    eqs(mm(function(t) { t.teams[0].members = []; }), "Alpha: at least one person", "tm engine: no members");
    eqs(mm(function(t) { t.teams[1].members = [{ id: "", name: "  " }]; }), "Beta: at least one person",
        "tm engine: whitespace-only member is nobody");
    eqs(mm(function(t) { t.teams[0].days = []; }), "Alpha: at least one day", "tm engine: no days");
    eqs(mm(function(t, c, p) { p[1] = { stops: [] }; }), "Beta: at least one stop", "tm engine: no stops");
    var nostops = JSON.parse(JSON.stringify(full)); nostops.teams[0].stops = [];
    eqs(CsTeams.missingAll(nostops, [null, plans[1]], contacts, [], true).join("|"), "Alpha: at least one stop",
        "tm engine: null plan means no stops");
    var none = { startDate: "", teams: [{ id: "a", name: "", members: [], stops: [], days: [] }] };
    eqs(CsTeams.missingAll(none, [null], {}, [], false).join("|"), ["start date", "topside contact name",
        "contact phone", "the if-no-word escalation line", "Team 1: a name", "Team 1: at least one person",
        "Team 1: at least one day", "Team 1: at least one stop"].join("|"), "tm engine: everything missing, panel order");
    // The roster is covered by each team's own "at least one person": the
    // trip-level roster line was dropped as a duplicate (Include roster ticked or not).
    var rost = CsTeams.missingAll(none, [null], {}, [], true);
    eqs(rost.length, 8, "tm engine: no duplicate trip-level roster line when nobody is on any team");
    ok(rost.join("|").indexOf("Include roster") < 0, "tm engine: no roster wording is added");
    var rost2 = CsTeams.missingAll(full, plans, contacts, [], true);
    eqs(rost2.length, 0, "tm engine: nothing missing when everyone is assigned");
    var half = JSON.parse(JSON.stringify(full)); half.teams[0].members = [];
    eqs(CsTeams.missingAll(half, plans, contacts, [], true).join("|"), "Alpha: at least one person",
        "tm engine: one empty team is reported by name only");
    eqs(CsTeams.missingAll(null, null, null, null, true).length > 0, true, "tm engine: missingAll never throws on null");

    // Slug, file name.
    eqs(CsTeams.slug("Deep Push!"), "deep-push", "tm engine: slug basic");
    eqs(CsTeams.slug(""), "team", "tm engine: slug empty");
    eqs(CsTeams.slug("***"), "team", "tm engine: slug all punctuation");
    eqs(CsTeams.slug("  Wet  --  Dry  "), "wet-dry", "tm engine: slug collapses hyphens");
    var long40 = "abcdefghij abcdefghij abcdefghij abcdefghij".slice(0, 40);
    eqs(CsTeams.slug(long40), "abcdefghij-abcdefghij-abcdefgh", "tm engine: slug cut to 30");
    eqs(CsTeams.slug("aaaaaaaaaaaaaaaaaaaaaaaaaaaaa bbbb").length <= 30, true, "tm engine: slug never over 30");
    eqs(CsTeams.slug("aaaaaaaaaaaaaaaaaaaaaaaaaaaaa bbbb"), "aaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
        "tm engine: slug trims a trailing hyphen after the cut");
    eqs(CsTeams.fileName(0, { name: "Deep Push!" }), "team-1-deep-push.html", "tm engine: fileName");
    eqs(CsTeams.fileName(2, { name: "" }), "team-3-team.html", "tm engine: fileName blank");

    // memberRows.
    var dir = [{ id: "p1", name: "Pat", role: "lead", medical: "asthma", emergency: "Mum 555" }];
    var rows = CsTeams.memberRows({ members: [{ id: "p1", name: "x" }, { id: "", name: "Stranger" }] }, dir);
    eqs(rows.length, 2, "tm engine: memberRows two");
    eqs(rows[0].known + "|" + rows[0].medical + "|" + rows[0].name, "true|asthma|Pat", "tm engine: known member resolved");
    eqs(rows[1].known + "|" + rows[1].name, "false|Stranger", "tm engine: unknown member");
    eqs(CsTeams.memberRows({ members: [] }, dir).length, 0, "tm engine: memberRows empty");
})();

// ---------------------------------------------------------------------
// Teams -- topside sheet and team file (CsCalloutCard.topsideHtml, teamHtml)
// ---------------------------------------------------------------------

(function() {
    // FROZEN copy of CsCalloutCard.html exactly as it was before the team
    // renderers (at 0b2a1da), with its two private helpers inlined. The
    // single-team card must stay byte-identical to this for every context.
    var tmWhen = function(stamp) { return stamp.date + " " + stamp.time; };
    var tmWet = function(day) {
        return day !== null && ((typeof day.rainChance === "number" &&
                day.rainChance >= CsCalloutCard.RAIN_CHANCE) ||
            (typeof day.rainTotal === "number" &&
                day.rainTotal >= CsCalloutCard.RAIN_INCHES));
    };
    var tmLegacyHtml = function(plan, ctx) {
        var esc = CsTripPlan.esc;
        var trip = ctx.trip;
        var contacts = ctx.contacts || {};
        var buffer = typeof contacts.bufferMin === "number" ? contacts.bufferMin : 120;
        var win = CsCalloutCard.windows(plan, trip, buffer);
        var hazards = CsCalloutCard.hazards(plan);
        var dates = CsCalloutCard.tripDates(trip);
        var h = [];
        h.push("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">");
        h.push("<title>" + esc(ctx.title) + " callout card</title>");
        h.push("<style>body{font:14px/1.4 -apple-system,Helvetica,Arial,sans-serif;" +
            "max-width:760px;margin:20px auto;padding:0 16px;color:#111}" +
            "h1{font-size:22px;margin:0 0 4px}h2{font-size:15px;margin:16px 0 4px;" +
            "border-bottom:1px solid #999}table{border-collapse:collapse;width:100%}" +
            "td,th{border:1px solid #bbb;padding:3px 6px;text-align:left;font-size:13px}" +
            ".note{color:#555}.warn{color:#8a4b00}.flag{font-weight:bold;color:#a00;" +
            "border:2px solid #a00;padding:4px 8px;margin:6px 0}" +
            ".box{border:3px solid #111;padding:8px 12px;margin:10px 0;font-size:17px}" +
            ".days{display:flex;gap:6px;flex-wrap:wrap}.day{border:1px solid #bbb;" +
            "padding:4px 8px;min-width:110px;display:flex;gap:8px;align-items:center}" +
            ".day .ico{flex:none;line-height:0}" +
            ".day .txt{font-size:12px}.day .txt b{font-size:14px}.page2{margin-top:32px}" +
            "@media print{.page2{page-break-before:always;margin-top:0}}" +
            CsTripPlan.SIGNS_CSS + "</style></head><body>");
        h.push("<h1>" + esc(ctx.title) + " &mdash; callout card</h1>");
        h.push("<p class=\"note\">" + esc(dates.length > 0 ? dates[0] : "") +
            (dates.length > 1 ? " to " + esc(dates[dates.length - 1]) : "") +
            (ctx.generated ? " &middot; made " + esc(ctx.generated) : "") + "</p>");

        // Roster: above the fold, straight under the header.
        h.push("<h2>Roster</h2>");
        if (ctx.includeRoster === false) {
            h.push("<p class=\"note\">Roster not included on this copy.</p>");
        } else if (!ctx.roster || ctx.roster.length === 0) {
            h.push("<p class=\"warn\">Roster not filled in.</p>");
        } else {
            h.push("<table><tr><th>Name</th><th>Role</th><th>Squeeze limit</th>" +
                "<th>Medical</th><th>Emergency contact</th><th>Skills</th></tr>");
            for (var r = 0; r < ctx.roster.length; r++) {
                var p = ctx.roster[r];
                if (p.known === false) {
                    // On the party, but not in this computer's directory.
                    h.push("<tr><td>" + esc(p.name) + "</td><td colspan=\"5\" " +
                        "class=\"note\">details not on this computer</td></tr>");
                    continue;
                }
                var labels = CsPeople.skillLabels(p);
                var escLabels = [];
                for (var sl = 0; sl < labels.length; sl++) { escLabels.push(esc(labels[sl])); }
                var note = p.skillsNote === undefined || p.skillsNote === null ?
                    "" : String(p.skillsNote);
                h.push("<tr><td>" + esc(p.name) + "</td><td>" + esc(p.role) + "</td><td>" +
                    (typeof p.squeeze === "number" ? esc(p.squeeze) + " in" : "&mdash;") +
                    "</td><td>" + esc(p.medical) + "</td><td>" + esc(p.emergency) +
                    "</td><td>" + escLabels.join(" &middot; ") +
                    (note.replace(/\s+/g, "") !== "" ? (escLabels.length > 0 ? "<br>" : "") +
                        "<span class=\"note\" style=\"font-size:11px\">" + esc(note) +
                        "</span>" : "") + "</td></tr>");
            }
            h.push("</table>");
        }

        h.push("<h2>Schedule</h2><table><tr><th>Day</th><th>Entry</th>" +
            "<th>Turnaround</th><th>Expected out</th><th>Callout</th></tr>");
        for (var w = 0; w < win.rows.length; w++) {
            var row = win.rows[w];
            h.push("<tr><td>" + row.day + "</td><td>" + esc(tmWhen(row.entry)) +
                "</td><td>" + esc(tmWhen(row.turnaround)) + "</td>");
            if (row.endsOnSurface) {
                h.push("<td>" + esc(tmWhen(row.expectedOut)) + "</td><td><b>" +
                    esc(tmWhen(row.callout)) + "</b></td></tr>");
            } else {
                h.push("<td colspan=\"2\" class=\"note\">Camp night, no callout until " +
                    "the team surfaces</td></tr>");
            }
        }
        h.push("</table>");
        for (var wn = 0; wn < win.warnings.length; wn++) {
            h.push("<p class=\"warn\">" + esc(win.warnings[wn]) + "</p>");
        }

        h.push("<h2>Escalation</h2><div class=\"box\">");
        if (!contacts.topName && !contacts.topPhone && !contacts.escalation) {
            h.push("<span class=\"warn\">Contacts not filled in.</span>");
        } else {
            h.push("Topside contact: <b>" + esc(contacts.topName) + "</b> " +
                esc(contacts.topPhone) + "<br>Callout buffer: " + esc(buffer) +
                " min after expected out.<br>" + esc(contacts.escalation));
        }
        h.push("</div>");

        h.push("<h2>Forecast</h2>");
        var anyWet = false;
        if (ctx.forecast === null || ctx.forecast === undefined) {
            h.push("<p class=\"warn\">No forecast, check before you go.</p>");
        } else {
            h.push("<div class=\"days\">");
            for (var d = 0; d < dates.length; d++) {
                var fd = null;
                for (var f = 0; f < ctx.forecast.days.length; f++) {
                    if (ctx.forecast.days[f].date === dates[d]) { fd = ctx.forecast.days[f]; }
                }
                if (fd === null) {
                    h.push("<div class=\"day\"><span class=\"txt\"><span class=\"note\">" +
                        esc(dates[d]) + "</span><br><span class=\"note\">" +
                        "outside forecast range</span></span></div>");
                } else {
                    var wet = tmWet(fd);
                    if (wet) { anyWet = true; }
                    var wxd = CsWeather.describeCode(fd.code) || CsWeather.fallbackKind(fd);
                    h.push("<div class=\"day\"" + (wet ? " style=\"border:2px solid #111\"" : "") + ">");
                    if (wxd !== null) {
                        h.push("<span class=\"ico\">" +
                            CsCalloutCard.weatherIconSvg(wxd.kind, wxd.label) + "</span>");
                    }
                    h.push("<span class=\"txt\"><span class=\"note\">" + esc(dates[d]) +
                        "</span><br>" + (wxd !== null ? "<b>" + esc(wxd.label) + "</b><br>" : "") +
                        esc(fd.high) + "&deg; / " + esc(fd.low) + "&deg; F<br>" +
                        "<span class=\"note\">rain " + esc(fd.rainTotal) + " in &middot; " +
                        esc(fd.rainChance) + "%</span></span></div>");
                }
            }
            h.push("</div>");
        }
        var anyWater = false;
        for (var hz = 0; hz < hazards.length; hz++) {
            if (hazards[hz].water) { anyWater = true; }
        }
        if (anyWet && anyWater) {
            h.push("<p class=\"flag\">Rain forecast + water noted on route. Check " +
                "conditions before going in.</p>");
        }

        // Page 2: the route.
        h.push("<div class=\"page2\"><h1>" + esc(ctx.title) + " &mdash; route</h1>");
        h.push("<p class=\"note\">This route follows the survey line. It is not a " +
            "guarantee that the way is safe or easy: crawls, water, climbs and loose " +
            "ground are only known where someone wrote them down.</p>");
        if (plan.stops.length === 0) {
            h.push("<p class=\"warn\">No route: add stops under Route in the Expedition Planner.</p>");
        } else {
            h.push(CsTripPlan.routeSvg(ctx.survey, ctx.resolved, plan));
            h.push("<h2>Directions</h2>");
            for (var s = 0; s < plan.stops.length; s++) {
                h.push("<h3>To " + esc(plan.stops[s].station) + "</h3>");
                var legIn = CsTripPlan.signs(plan.stops[s].steps, plan.unit,
                    plan.stops[s].station);
                h.push(CsTripPlan.legSummaryHtml(legIn, plan.stops[s].steps, plan.unit));
                h.push(CsTripPlan.signsHtml(legIn));
            }
            h.push("<h3>Back to " + esc(plan.start) + "</h3>");
            var legOut = CsTripPlan.signs(plan.back.steps, plan.unit, plan.start);
            h.push(CsTripPlan.legSummaryHtml(legOut, plan.back.steps, plan.unit));
            h.push(CsTripPlan.signsHtml(legOut));
        }
        h.push("<h2>Hazards on the route</h2>");
        if (hazards.length === 0) {
            h.push("<p class=\"note\">None noted. Notes only exist where someone wrote them.</p>");
        } else {
            h.push("<ul>");
            for (var z = 0; z < hazards.length; z++) {
                h.push("<li class=\"warn\">" + esc(hazards[z].station) + ": " +
                    esc(hazards[z].text) + "</li>");
            }
            h.push("</ul>");
        }
        if (plan.gear && plan.gear.rope.length > 0) {
            h.push("<h2>Rope and hardware</h2><ul>");
            for (var ro = 0; ro < plan.gear.rope.length; ro++) {
                h.push("<li>" + esc(plan.gear.rope[ro].text) + "</li>");
            }
            for (var hw = 0; hw < plan.gear.hardware.length; hw++) {
                h.push("<li class=\"warn\">" + esc(plan.gear.hardware[hw]) + "</li>");
            }
            h.push("</ul>");
        }
        h.push("</div></body></html>");
        return h.join("\n");
    };

    var firstDiff = function(a, b) {
        var n = Math.min(a.length, b.length);
        for (var i = 0; i < n; i++) { if (a.charAt(i) !== b.charAt(i)) { return i; } }
        return a.length === b.length ? -1 : n;
    };
    var parity = function(plan, over, what) {
        var now = CsCalloutCard.html(plan, ccCtx(over));
        var then = tmLegacyHtml(plan, ccCtx(over));
        var at = firstDiff(now, then);
        ok(at < 0, "tm render: single-team card byte-identical, " + what +
            (at < 0 ? "" : " (first difference at char " + at + ": now '" +
                now.slice(Math.max(0, at - 40), at + 40) + "' was '" +
                then.slice(Math.max(0, at - 40), at + 40) + "')"));
        ok(then.length > 1500, "tm render: parity reference is a real page, " + what);
    };
    var wxFc = { days: [
        { date: "2026-10-03", high: 73, low: 70, rainTotal: 0.54, rainChance: 57, code: 63 },
        { date: "2026-10-04", high: 66, low: 51, rainTotal: 0, rainChance: 5, code: 0 },
        { date: "2026-10-05", high: 64, low: 50, rainTotal: 0, rainChance: 5 } ] };
    var noRoute = CsTripPlan.build(tpSurvey(), tpResolved, { start: "A1", targets: [], unit: "ft" });
    parity(ccRealPlan, {}, "roster and no forecast");
    parity(ccWaterPlan, { includeRoster: false, forecast: wxFc }, "roster off, forecast with icons, water flag");
    parity(ccRealPlan, { roster: [ { id: "", name: "Stranger & Co", role: "", squeeze: null,
        medical: "", emergency: "", skills: [], skillsNote: "", known: false } ] }, "unknown member");
    parity(ccRealPlan, { roster: [] }, "empty roster");
    parity(ccRealPlan, { contacts: {} }, "no contacts");
    parity(ccRealPlan, { forecast: wxFc, trip: { startDate: "2026-10-03", days: [
        { entry: "08:00", workHours: 30, night: "camp" }, { entry: "08:00", workHours: 3, night: "out" },
        { entry: "09:00", workHours: 2, night: "out" } ] } }, "camp night, overrun warning, three days");
    parity(noRoute, {}, "no route");

    // Two teams. Alpha: 2 days from the start; Beta: 1 day, a day later, an
    // early entry, so its callout falls BETWEEN Alpha's two (unsorted input).
    var dir = [
        { id: "p-ana", name: "Ana <b>Ruiz</b>", role: "Lead", squeeze: 14, medical: "Asthma",
          emergency: "Luis 555-0111", skills: ["first_aid"], skillsNote: "SRT <i>2019</i>" },
        { id: "p-bo", name: "Bo", role: "Sketch", squeeze: "", medical: "None",
          emergency: "Mum 555-0122", skills: [], skillsNote: "" } ];
    var trip = { startDate: "2026-10-03", weatherPlace: "", teams: [
        { id: "t1", name: "Alpha", goal: "Survey the A passage", dayOffset: 0,
          members: [ { id: "p-ana", name: "Ana" }, { id: "", name: "Stranger" } ], stops: ["A3"],
          days: [ { entry: "08:00", workHours: 4, night: "out" },
                  { entry: "09:00", workHours: 4, night: "out" } ],
          packing: "First aid <b>kit</b>\nSpare batteries" },
        { id: "t2", name: "Beta", goal: "Push the creek", dayOffset: 1,
          members: [ { id: "p-ana", name: "Ana" }, { id: "p-bo", name: "Bo" } ], stops: ["A3"],
          days: [ { entry: "05:00", workHours: 1, night: "out" } ], packing: "" } ] };
    var contacts = { topName: "Pat Topside", topPhone: "555-0100",
        escalation: "Call the rescue coordinator, 555-0199.", bufferMin: 120 };
    var plans = [ccRealPlan, ccWaterPlan];
    var entry = function(i, plan) {
        var team = trip.teams[i];
        return { team: team, plan: plan, windows: CsTeams.windows(plan, trip, team, 120),
            members: CsTeams.memberRows(team, dir), survey: tpSurvey(), resolved: tpResolved };
    };
    var fileNames = [CsTeams.fileName(0, trip.teams[0]), CsTeams.fileName(1, trip.teams[1])];
    var topCtx = function(over) {
        var c = { title: "Test Cave", trip: trip, teams: [entry(0, plans[0]), entry(1, plans[1])],
            contacts: contacts, includeRoster: true, forecast: wxFc, generated: "2026-09-29",
            fileNames: fileNames };
        for (var k in over) { c[k] = over[k]; }
        return c;
    };
    var teamCtx = function(i, plan, over) {
        var e = entry(i, plan);
        var c = { title: "Test Cave", trip: trip, team: e.team, plan: plan, windows: e.windows,
            members: e.members, forecast: wxFc, generated: "2026-09-29",
            survey: tpSurvey(), resolved: tpResolved };
        for (var k in over) { c[k] = over[k]; }
        return c;
    };
    var top = CsCalloutCard.topsideHtml(topCtx({}));
    var at = function(s) { return top.indexOf(s); };

    // Order of the sections.
    ok(at("<h1>") >= 0 && at("<h1>") < at("<h2>Next callouts</h2>") &&
        at("<h2>Next callouts</h2>") < at("<h2>Roster</h2>") &&
        at("<h2>Roster</h2>") < at("is on Alpha and Beta") &&
        at("is on Alpha and Beta") < at("<h2>Schedule") &&
        at("<h2>Schedule") < at("<h2>Escalation</h2>") &&
        at("<h2>Escalation</h2>") < at("<h2>Forecast</h2>"),
        "tm render: topside sections in order: header, strip, roster, conflicts, schedules, escalation, forecast");
    ok(top.indexOf("<!doctype html>") === 0 && top.indexOf("</body></html>") > 0,
        "tm render: topside is a whole page");

    // The next-callouts strip, sorted by time across teams.
    var wA = CsTeams.windows(ccRealPlan, trip, trip.teams[0], 120);
    var wB = CsTeams.windows(ccWaterPlan, trip, trip.teams[1], 120);
    ok(wA.rows[0].callout.abs < wB.rows[0].callout.abs &&
        wB.rows[0].callout.abs < wA.rows[1].callout.abs,
        "tm render: fixture puts Beta's callout between Alpha's two");
    var stripPart = top.slice(at("<h2>Next callouts</h2>"), at("<h2>Roster</h2>"));
    var stripText = stripPart.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ")
        .replace(/^\s+|\s+$/g, "");
    var want = [];
    var ws = [wA.rows[0].callout, wB.rows[0].callout, wA.rows[1].callout];
    var wn = ["Alpha", "Beta", "Alpha"];
    for (var s = 0; s < ws.length; s++) { want.push(ws[s].date + " " + ws[s].time + " " + wn[s] + " callout"); }
    eqs(stripText, "Next callouts " + want.join(" "), "tm render: strip lists every callout sorted by time");

    // Roster grouped by team; Ana under both.
    var rosterPart = top.slice(at("<h2>Roster</h2>"), at("<h2>Schedule"));
    var alphaAt = rosterPart.indexOf("<h3>Alpha</h3>");
    var betaAt = rosterPart.indexOf("<h3>Beta</h3>");
    ok(alphaAt > 0 && betaAt > alphaAt, "tm render: roster has a heading per team, in team order");
    eqs(rosterPart.split("Ana &lt;b&gt;Ruiz&lt;/b&gt;").length, 3,
        "tm render: a person on two teams is listed under each");
    ok(rosterPart.indexOf("<b>Ruiz") < 0, "tm render: member name escaped on the topside");
    eqs(rosterPart.split("Luis 555-0111").length, 3, "tm render: topside roster has the emergency contact");
    ok(rosterPart.indexOf("14 in") > 0 && rosterPart.indexOf("Asthma") > 0 &&
        rosterPart.indexOf("Lead") > 0 && rosterPart.indexOf("First aid trained") > 0 &&
        rosterPart.indexOf("SRT &lt;i&gt;2019&lt;/i&gt;") > 0,
        "tm render: topside roster rows carry role, squeeze, skills and note, medical");
    var stranger = rosterPart.indexOf("Stranger");
    ok(stranger > alphaAt && stranger < betaAt, "tm render: unknown member under their team");
    eqs(rosterPart.split("details not on this computer").length, 2,
        "tm render: unknown member prints the placeholder once");
    var boAt = rosterPart.indexOf(">Bo<");
    ok(boAt > betaAt, "tm render: Bo only under Beta");

    // Same-day conflict banner.
    ok(top.indexOf("<b>Ana is on Alpha and Beta on 2026-10-04</b>") > 0,
        "tm render: same-day conflict is a bold warning");
    var soloTrip = JSON.parse(JSON.stringify(trip));
    soloTrip.teams[1].members = [ { id: "p-bo", name: "Bo" } ];
    var solo = CsCalloutCard.topsideHtml(topCtx({ trip: soloTrip }));
    ok(solo.indexOf(" is on ") < 0, "tm render: no conflict, no warning");

    // One schedule table per team with name, goal and file name.
    var schedPart = top.slice(at("<h2>Schedule"), at("<h2>Escalation</h2>"));
    eqs(schedPart.split("<th>Callout</th>").length, 3, "tm render: one schedule table per team");
    var sA = schedPart.indexOf("Alpha");
    var sB = schedPart.indexOf("Beta");
    ok(sA >= 0 && sB > sA, "tm render: schedule tables in team order");
    ok(schedPart.indexOf("Survey the A passage") > 0 && schedPart.indexOf("Push the creek") > 0,
        "tm render: schedule headings carry the goals");
    ok(schedPart.indexOf(fileNames[0]) > 0 && schedPart.indexOf(fileNames[1]) > 0 &&
        schedPart.indexOf(fileNames[0]) < sB && schedPart.indexOf(fileNames[1]) > sB,
        "tm render: each schedule names its team file");
    ok(schedPart.indexOf(wB.rows[0].callout.date + " " + wB.rows[0].callout.time) > sB,
        "tm render: Beta's callout in Beta's table");

    // Escalation, forecast, flag; no route.
    ok(top.indexOf("Pat Topside") > 0 && top.indexOf("555-0199") > 0, "tm render: escalation box");
    var fcPart = top.slice(at("<h2>Forecast</h2>"));
    ok(fcPart.indexOf("role=\"img\"") > 0, "tm render: topside forecast keeps the weather icons");
    ok(fcPart.indexOf("2026-10-03") > 0 && fcPart.indexOf("2026-10-04") > 0 &&
        fcPart.indexOf("2026-10-05") < 0, "tm render: topside forecast covers the trip's dates only");
    ok(top.indexOf("Rain forecast + water noted on route") > 0,
        "tm render: rain on a trip day plus water on any team's route raises the flag");
    var dryTop = CsCalloutCard.topsideHtml(topCtx({ teams: [entry(0, ccRealPlan), entry(1, ccRealPlan)] }));
    ok(dryTop.indexOf("Rain forecast + water noted on route") < 0, "tm render: no water note, no flag");
    ok(top.indexOf("xmlns=\"http://www.w3.org/2000/svg\"") < 0, "tm render: no route drawing on the topside");
    ok(top.indexOf("Directions") < 0 && top.indexOf("Back to") < 0, "tm render: no directions on the topside");
    // Weather icons carry float noise in their static sun-ray paths
    // (31.799999999999997, same as the single-team card): not coordinates.
    var noIcons = function(x) { return x.replace(/<span class="ico"><svg[\s\S]*?<\/svg><\/span>/g, ""); };
    ok(!/-?\d{2}\.\d{3,}/.test(noIcons(top)), "tm render: topside has no long decimal that could be a coordinate");
    ok(noIcons(top).indexOf("<svg") < 0, "tm render: only the weather icons were set aside for that check");
    var noFc = CsCalloutCard.topsideHtml(topCtx({ forecast: null }));
    ok(noFc.indexOf("No forecast, check before you go") > 0, "tm render: topside with no forecast");

    // Roster off.
    var off = CsCalloutCard.topsideHtml(topCtx({ includeRoster: false }));
    ok(off.indexOf("Roster not included on this copy.") > 0, "tm render: roster-off line on the topside");
    ok(off.indexOf("Ana") < 0 && off.indexOf("Luis") < 0 && off.indexOf("Asthma") < 0,
        "tm render: roster off prints no names or details");
    ok(off.indexOf("<th>Callout</th>") > 0, "tm render: roster off keeps the schedules");

    // The team file.
    var fa = CsCalloutCard.teamHtml(teamCtx(0, ccRealPlan, {}));
    var faSplit = fa.indexOf("class=\"page2\"");
    var faTop = fa.slice(0, faSplit);
    ok(fa.indexOf("<!doctype html>") === 0 && faSplit > 0, "tm render: team file is a page with a page-2 marker");
    ok(faTop.indexOf("Alpha") > 0 && faTop.indexOf("Survey the A passage") > 0,
        "tm render: team file has team name and goal");
    ok(faTop.indexOf("2026-10-03") > 0 && faTop.indexOf("2026-10-04") > 0,
        "tm render: team file has its dates");
    ok(faTop.indexOf("Ana &lt;b&gt;Ruiz&lt;/b&gt;") > 0 && faTop.indexOf("Asthma") > 0 &&
        faTop.indexOf("14 in") > 0 && faTop.indexOf("Lead") > 0 && faTop.indexOf("First aid trained") > 0,
        "tm render: team file members with role, squeeze, skills, medical");
    ok(fa.indexOf("Luis") < 0 && fa.indexOf("555-0111") < 0 && fa.indexOf("Emergency") < 0 &&
        fa.indexOf("emergency") < 0, "tm render: team file carries no emergency contact");
    ok(faTop.indexOf("Stranger") > 0 && faTop.indexOf("details not on this computer") > 0,
        "tm render: team file unknown member placeholder");
    eqs(faTop.split("<th>Callout</th>").length, 2, "tm render: team file has its schedule table");
    ok(faTop.indexOf(tmWhen(wA.rows[1].callout)) > 0, "tm render: team file schedule has its day 2 callout");
    ok(faTop.indexOf("xmlns=\"http://www.w3.org/2000/svg\"") < 0 &&
        fa.slice(faSplit).indexOf("xmlns=\"http://www.w3.org/2000/svg\"") > 0,
        "tm render: the route drawing comes after the page break");
    ok(fa.slice(faSplit).indexOf("<h2>Directions</h2>") > 0 && fa.indexOf("Back to A1") > 0,
        "tm render: team file has the directions");
    ok(fa.indexOf("First aid &lt;b&gt;kit&lt;/b&gt;<br>Spare batteries") > 0,
        "tm render: team packing printed, escaped, line breaks kept");
    ok(!/-?\d{2}\.\d{3,}/.test(noIcons(faTop)), "tm render: team file page 1 has no long decimal");
    ok(fa.indexOf("Pat Topside") < 0 && fa.indexOf("Contacts not filled in.") > 0,
        "tm render: team file without contacts prints the escalation fallback");
    var faFc = faTop.slice(faTop.indexOf("<h2>Forecast</h2>"));
    ok(faFc.indexOf("2026-10-03") > 0 && faFc.indexOf("2026-10-04") > 0 &&
        faFc.indexOf("2026-10-05") < 0, "tm render: team file forecast is its own dates");

    var fb = CsCalloutCard.teamHtml(teamCtx(1, ccWaterPlan, {}));
    var fbTop = fb.slice(0, fb.indexOf("class=\"page2\""));
    var fbFc = fbTop.slice(fbTop.indexOf("<h2>Forecast</h2>"));
    ok(fbFc.indexOf("2026-10-04") > 0 && fbFc.indexOf("2026-10-03") < 0,
        "tm render: a day-2 team's forecast leaves out the trip's first day");
    ok(fb.indexOf("Rain forecast + water noted on route") < 0,
        "tm render: team file flag only for its own wet days");
    ok(fb.indexOf("creek crossing") > 0, "tm render: team file lists hazards on its route");
    ok(fb.indexOf("Mum") < 0 && fb.indexOf("Luis") < 0, "tm render: no emergency contacts for Beta either");
    var fbOut = CsCalloutCard.teamHtml(teamCtx(1, ccWaterPlan, { forecast: { days: [ wxFc.days[0] ] } }));
    ok(fbOut.indexOf("outside forecast range") > 0, "tm render: team file day outside the forecast");

    // No route degrades.
    var fn = CsCalloutCard.teamHtml(teamCtx(0, noRoute, {}));
    ok(fn.indexOf("No route: add stops under this team") > 0, "tm render: no-route team says so");
    ok(fn.indexOf("xmlns=\"http://www.w3.org/2000/svg\"") < 0, "tm render: no-route team has no drawing");
    var tn = CsCalloutCard.topsideHtml(topCtx({ teams: [entry(0, noRoute), entry(1, ccWaterPlan)] }));
    ok(tn.indexOf("<h2>Forecast</h2>") > 0, "tm render: a no-route team does not break the topside");

    // Escaping everywhere.
    var evil = JSON.parse(JSON.stringify(trip));
    evil.teams[0].name = "<b>Deep</b>";
    evil.teams[0].goal = "<b>go</b> far";
    evil.teams[0].packing = "<b>rope</b>";
    evil.teams[0].members = [ { id: "", name: "<b>Zed</b>" } ];
    evil.teams[1].members = [ { id: "", name: "<b>Zed</b>" } ];
    var evTeam = function(i, plan) {
        var t = evil.teams[i];
        return { team: t, plan: plan, windows: CsTeams.windows(plan, evil, t, 120),
            members: CsTeams.memberRows(t, dir), survey: tpSurvey(), resolved: tpResolved };
    };
    var evTop = CsCalloutCard.topsideHtml(topCtx({ trip: evil, teams: [evTeam(0, ccRealPlan), evTeam(1, ccWaterPlan)],
        fileNames: [CsTeams.fileName(0, evil.teams[0]), CsTeams.fileName(1, evil.teams[1])] }));
    var e0 = evTeam(0, ccRealPlan);
    var evFile = CsCalloutCard.teamHtml({ title: "Test <b>Cave</b>", trip: evil, team: e0.team, plan: ccRealPlan,
        windows: e0.windows, members: e0.members, forecast: wxFc, generated: "2026-09-29",
        survey: tpSurvey(), resolved: tpResolved });
    var raw = ["<b>Deep", "<b>go", "<b>rope", "<b>Zed", "<b>Cave"];
    for (var r = 0; r < raw.length; r++) {
        ok(evTop.indexOf(raw[r]) < 0, "tm render: topside has no raw " + raw[r]);
        ok(evFile.indexOf(raw[r]) < 0, "tm render: team file has no raw " + raw[r]);
    }
    ok(evTop.indexOf("&lt;b&gt;Deep&lt;/b&gt;") > 0 && evTop.indexOf("&lt;b&gt;go&lt;/b&gt; far") > 0 &&
        evTop.indexOf("&lt;b&gt;Zed&lt;/b&gt;") > 0, "tm render: topside escapes team name, goal, member");
    ok(evTop.indexOf("&lt;b&gt;Zed&lt;/b&gt; is on &lt;b&gt;Deep&lt;/b&gt; and Beta on 2026-10-04") > 0,
        "tm render: conflict banner escaped");
    ok(evFile.indexOf("&lt;b&gt;Deep&lt;/b&gt;") > 0 && evFile.indexOf("&lt;b&gt;go&lt;/b&gt; far") > 0 &&
        evFile.indexOf("&lt;b&gt;rope&lt;/b&gt;") > 0 && evFile.indexOf("&lt;b&gt;Zed&lt;/b&gt;") > 0,
        "tm render: team file escapes team name, goal, packing, member");

    // The team file carries the trip's escalation box: a team underground
    // must know who topside is. Trip-level contacts only, never a member's.
    var fe = CsCalloutCard.teamHtml(teamCtx(0, ccRealPlan, { contacts: contacts }));
    var feTop = fe.slice(0, fe.indexOf("class=\"page2\""));
    var feEsc = feTop.indexOf("<h2>Escalation</h2>");
    ok(feEsc > feTop.indexOf("<th>Callout</th>") && feEsc < feTop.indexOf("<h2>Forecast</h2>"),
        "tm render: team file escalation box sits under the schedule, before the forecast");
    ok(feTop.indexOf("Pat Topside") > feEsc && feTop.indexOf("555-0100") > feEsc &&
        feTop.indexOf("Call the rescue coordinator, 555-0199.") > feEsc,
        "tm render: team file shows the topside contact, phone and escalation line");
    ok(feTop.indexOf("Callout buffer: 120 min after expected out.") > feEsc,
        "tm render: team file escalation box carries the buffer wording");
    ok(fe.indexOf("Luis") < 0 && fe.indexOf("555-0111") < 0 && fe.indexOf("Mum") < 0 &&
        fe.indexOf("Emergency") < 0 && fe.indexOf("emergency") < 0,
        "tm render: team file with the escalation box still has no member emergency contact");
    var fe90 = CsCalloutCard.teamHtml(teamCtx(0, ccRealPlan, { contacts: { topName: "Pat Topside",
        topPhone: "555-0100", escalation: "E", bufferMin: 90 } }));
    ok(fe90.indexOf("Callout buffer: 90 min after expected out.") > 0,
        "tm render: team file uses the trip's own buffer");
    var feNull = CsCalloutCard.teamHtml(teamCtx(0, ccRealPlan, { contacts: null }));
    ok(feNull.indexOf("<h2>Escalation</h2>") > 0 && feNull.indexOf("Contacts not filled in.") > 0,
        "tm render: team file with null contacts prints the fallback");
    var feEmpty = CsCalloutCard.teamHtml(teamCtx(0, ccRealPlan, { contacts: {} }));
    ok(feEmpty.indexOf("Contacts not filled in.") > 0,
        "tm render: team file with empty contacts prints the fallback");
    var feEvil = CsCalloutCard.teamHtml(teamCtx(0, ccRealPlan, { contacts: { topName: "<b>Pat</b>",
        topPhone: "1", escalation: "<i>x</i>", bufferMin: 120 } }));
    ok(feEvil.indexOf("<b>Pat") < 0 && feEvil.indexOf("&lt;b&gt;Pat&lt;/b&gt;") > 0 &&
        feEvil.indexOf("<i>x") < 0, "tm render: team file escalation box is escaped");
})();

// ---------------------------------------------------------------------
// Teams -- the panel's data layer (ExpeditionPlanner team state, load,
// edits, write-through). The sidecar and child() are stubbed.
// ---------------------------------------------------------------------
(function() {
    var EP = ExpeditionPlanner;
    var fns = ["loadTeams", "addTeam", "removeTeam", "setTeamField", "setTeamMember",
        "teamMemberFlags", "addTeamStop", "removeTeamStop", "clearTeamStops", "setTeamDays",
        "saveTeams", "teamWarnings"];
    var absent = [];
    for (var f = 0; f < fns.length; f++) {
        if (typeof EP[fns[f]] !== "function") { absent.push(fns[f]); }
    }
    eqs(absent.join(","), "", "tm panel: the team functions exist");
    if (absent.length > 0) { return; }
    var realState = EP.state;
    var realChild = EP.child;
    var realPath = CsStationSidecar.sidecarPath;
    var realRead = CsStationSidecar.readSidecar;
    var realWrite = CsStationSidecar.writeSidecar;
    var disk = { text: "", writes: 0, damaged: false };
    CsStationSidecar.sidecarPath = function(docPath) {
        return (docPath === "" || docPath === null || docPath === undefined) ? "" :
            "/fake/Cave/stations.json";
    };
    CsStationSidecar.readSidecar = function(path) {
        if (disk.damaged) {
            return { store: CsStationStore.empty(), error: "stations.json could not be read: broken" };
        }
        return CsStationStore.parse(disk.text);
    };
    CsStationSidecar.writeSidecar = function(path, st) {
        disk.writes++;
        disk.text = CsStationStore.serialize(st);
        return true;
    };
    EP.child = function() { return null; };
    var party = [ { id: "p-ana", name: "Ana" }, { id: "p-bo", name: "Bo" }, { id: "", name: "Cy" } ];
    var day = function(e, h, n) { return { entry: e, workHours: h, night: n }; };
    // Put `settings` on the fake disk and load the panel from it, as
    // reload() + showCalloutSettings() do.
    var open = function(settings, docPath) {
        disk.text = JSON.stringify({ version: CsStationStore.VERSION,
            entries: [ { station: "A2", note: "keep me", status: "", team: "", who: "" } ],
            settings: settings });
        disk.writes = 0;
        disk.damaged = false;
        var parsed = CsStationStore.parse(disk.text);
        EP.state = { drawn: null, docPath: docPath === undefined ? "/fake/Cave/Cave.dxf" : docPath,
            store: parsed.store, loadError: "", stations: ["A1", "A2", "B20", "D8"],
            planStops: [], plan: null, planShown: null, people: [], peopleError: "",
            rosterRows: [], filling: false, teams: [] };
        return EP.loadTeams(parsed.store.settings.trip, parsed.store.settings);
    };
    var onDisk = function() { return CsStationStore.parse(disk.text).store.settings; };
    var stored = function() {
        return { packing: "old list", pace: { paceFtPerMin: 100, rig: 5 },
            trip: { startDate: "2026-10-03", party: party, days: [day("07:00", 2, "out")],
                teams: [ { id: "t1", name: "Alpha", goal: "A", dayOffset: 0,
                    members: [ { id: "p-ana", name: "Ana" } ], stops: ["B20"],
                    days: [day("08:00", 4, "out")], packing: "rope" },
                  { id: "t2", name: "Beta", goal: "", dayOffset: 1, members: [], stops: [],
                    days: [day("09:00", 3, "out")], packing: "" } ] } };
    };
    var team = function(i) { return EP.state.teams[i]; };
    try {
        ok(realState.teams !== undefined && realState.teams.length === 0,
            "tm panel: state.teams starts empty");

        // Load: stored teams as they are.
        var got = open(stored());
        ok(got === EP.state.teams, "tm panel: loadTeams returns state.teams");
        eqs(EP.state.teams.length, 2, "tm panel: stored teams load");
        eqs(team(0).id + "," + team(0).name + "," + team(0).packing + "," + team(1).dayOffset,
            "t1,Alpha,rope,1", "tm panel: stored teams load as they are (no migration)");
        eqs(disk.writes, 0, "tm panel: loading writes nothing");
        team(0).name = "changed";
        eqs(EP.state.store.settings.trip.teams[0].name, "Alpha",
            "tm panel: state.teams is a copy, not the store's own list");

        // Load: legacy days -> Team 1 with the days, packing and party.
        open({ packing: "Helmet\nLights", trip: { startDate: "2026-10-03", party: party,
            days: [day("08:00", 5, "out"), day("08:30", 6, "camp")] } });
        eqs(EP.state.teams.length, 1, "tm panel: a legacy trip becomes one team");
        eqs(team(0).name, "Team 1", "tm panel: the migrated team is Team 1");
        eqs(JSON.stringify(team(0).days),
            JSON.stringify([day("08:00", 5, "out"), day("08:30", 6, "camp")]),
            "tm panel: the migrated team holds the legacy days");
        eqs(team(0).packing, "Helmet\nLights", "tm panel: the migrated team holds settings.packing");
        eqs(JSON.stringify(team(0).members), JSON.stringify(party),
            "tm panel: the migrated team's members are the party");
        ok(team(0).id !== "", "tm panel: the migrated team has an id");
        eqs(disk.writes, 0, "tm panel: migration at load writes nothing");
        var mid = team(0).id;
        eqs(EP.saveTeams(), "", "tm panel: the migrated team saves");
        eqs(onDisk().trip.teams.length, 1, "tm panel: load-then-save of a legacy trip writes exactly one team");
        var again = CsStationStore.parse(disk.text).store;
        EP.state.store = again;
        EP.loadTeams(again.settings.trip, again.settings);
        eqs(EP.state.teams.length + ":" + team(0).id, "1:" + mid,
            "tm panel: reloading the saved trip loads that team, no second migration");
        EP.saveTeams();
        eqs(onDisk().trip.teams.length, 1, "tm panel: a second load-save cycle still holds one team");
        eqs(onDisk().trip.days.length, 2, "tm panel: the legacy days are left in the file");
        eqs(onDisk().packing, "Helmet\nLights", "tm panel: settings.packing is left in the file");

        // Load: an empty trip -> one empty Team 1.
        open({});
        eqs(EP.state.teams.length, 1, "tm panel: an empty trip gets one team");
        eqs(team(0).name + "|" + team(0).members.length + "|" + team(0).stops.length + "|" +
            team(0).days.length + "|" + team(0).packing + "|" + team(0).dayOffset,
            "Team 1|0|0|0||0", "tm panel: that team is an empty Team 1");
        EP.loadTeams(null, null);
        eqs(EP.state.teams.length + ":" + team(0).name, "1:Team 1",
            "tm panel: no trip at all still gives one empty Team 1");
        // A stored team without an id (allowed in the file) gets one.
        open({ trip: { startDate: "2026-10-03", teams: [ { name: "A" }, { id: "x", name: "B" },
            { id: "x", name: "C" } ] } });
        ok(team(0).id !== "" && team(2).id !== "x" && team(2).id !== "" && team(1).id === "x",
            "tm panel: missing and repeated team ids get fresh ones at load");

        // addTeam / removeTeam.
        open(stored());
        var r = EP.addTeam();
        ok(r.done === true && r.why === "", "tm panel: addTeam adds and saves");
        eqs(EP.state.teams.length, 3, "tm panel: three teams after an add");
        var t3 = team(2);
        ok(r.team === t3, "tm panel: addTeam returns the new team");
        eqs(t3.name, "Team 3", "tm panel: a new team is named Team N");
        ok(t3.id !== "" && t3.id !== "t2", "tm panel: a new team has a fresh id");
        eqs(JSON.stringify(t3.days) + "|" + t3.dayOffset, JSON.stringify([day("09:00", 3, "out")]) + "|1",
            "tm panel: a new team copies the last team's days and dayOffset");
        eqs(t3.members.length + t3.stops.length + t3.packing.length + t3.goal.length, 0,
            "tm panel: a new team has no members, stops, packing or goal");
        eqs(onDisk().trip.teams.length, 3, "tm panel: the new team is written through");
        while (EP.state.teams.length < 8) { EP.addTeam(); }
        var w8 = disk.writes;
        var r9 = EP.addTeam();
        ok(r9.done === false && r9.why !== "", "tm panel: a ninth team is refused with a reason");
        eqs(EP.state.teams.length + ":" + disk.writes, "8:" + w8, "tm panel: the refused add changes and writes nothing");
        eqs(team(7).name, "Team 8", "tm panel: the eighth team is Team 8");
        var rr = EP.removeTeam(team(7).id);
        ok(rr.done === true && rr.why === "", "tm panel: removeTeam removes and saves");
        eqs(EP.state.teams.length + ":" + onDisk().trip.teams.length, "7:7",
            "tm panel: the removal is written through");
        ok(EP.removeTeam("nope").done === false, "tm panel: removing an unknown team is refused");
        while (EP.state.teams.length > 1) { EP.removeTeam(team(EP.state.teams.length - 1).id); }
        var wl = disk.writes;
        var rl = EP.removeTeam(team(0).id);
        ok(rl.done === false && rl.why !== "", "tm panel: the last team cannot be removed");
        eqs(EP.state.teams.length + ":" + disk.writes, "1:" + wl, "tm panel: the refused removal writes nothing");
        open({ trip: { startDate: "2026-10-03", teams: [ { id: "a", name: "Alpha" }, { id: "b", name: "Team 3" } ] } });
        eqs(EP.addTeam().team.name, "Team 4", "tm panel: a new team's name skips one already taken");

        // Setters validate through cleanTeam.
        open(stored());
        EP.setTeamField("t2", "name", "   ");
        eqs(team(1).name, "Team 2", "tm panel: a blank name becomes Team N");
        EP.setTeamField("t2", "name", "  Deep  ");
        eqs(team(1).name, "Deep", "tm panel: the name is trimmed");
        EP.setTeamField("t2", "goal", "  Push the creek ");
        eqs(team(1).goal, "Push the creek", "tm panel: the goal is trimmed");
        EP.setTeamField("t2", "packing", "Rope\nBolts");
        eqs(team(1).packing, "Rope\nBolts", "tm panel: packing is set");
        EP.setTeamField("t2", "dayOffset", -2);
        eqs(team(1).dayOffset, 0, "tm panel: a negative dayOffset is 0");
        EP.setTeamField("t2", "dayOffset", 2);
        eqs(team(1).dayOffset, 2, "tm panel: dayOffset is set");
        EP.setTeamField("t2", "dayOffset", "3");
        eqs(team(1).dayOffset, 3, "tm panel: a whole-number text dayOffset is read");
        EP.setTeamField("t2", "dayOffset", 1.5);
        eqs(team(1).dayOffset, 0, "tm panel: a fractional dayOffset is 0");
        var rf = EP.setTeamField("t2", "medical", "x");
        ok(rf.done === false && team(1).medical === undefined, "tm panel: an unknown field is refused");
        ok(EP.setTeamField("nope", "name", "x").done === false, "tm panel: an unknown team is refused");
        eqs(onDisk().trip.teams[1].name + "|" + onDisk().trip.teams[1].goal + "|" +
            onDisk().trip.teams[1].packing, "Deep|Push the creek|Rope\nBolts",
            "tm panel: field edits are written through");
        EP.setTeamDays("t2", [day("7:05", 3, "camp"), day("25:00", 1, "out"), day("10:00", 2, "bogus")]);
        eqs(JSON.stringify(team(1).days), JSON.stringify([day("07:05", 3, "camp"), day("10:00", 2, "out")]),
            "tm panel: setTeamDays cleans the days like trip days");
        eqs(JSON.stringify(onDisk().trip.teams[1].days), JSON.stringify(team(1).days),
            "tm panel: the days are written through");
        EP.setTeamDays("t2", "junk");
        eqs(team(1).days.length, 0, "tm panel: junk days are no days");

        // Stops: real stations only, the station's own name, no duplicates.
        var sr = EP.addTeamStop("t2", " b20 ");
        ok(sr.done === true, "tm panel: a real station is added");
        eqs(team(1).stops.join(","), "B20", "tm panel: a case-blind match adds the station's own name");
        var sd = EP.addTeamStop("t2", "B20");
        ok(sd.done === false && sd.why === "", "tm panel: a stop already there changes nothing, silently");
        eqs(team(1).stops.join(","), "B20", "tm panel: stops stay deduped");
        var sb = EP.addTeamStop("t2", "Z99");
        ok(sb.done === false && sb.why.indexOf("Z99") >= 0, "tm panel: a station not in the drawing is refused, named");
        ok(EP.addTeamStop("t2", "  ").done === false, "tm panel: a blank stop is refused");
        EP.addTeamStop("t2", "D8");
        eqs(team(1).stops.join(",") + "|" + onDisk().trip.teams[1].stops.join(","), "B20,D8|B20,D8",
            "tm panel: stops kept in order and written through");
        EP.removeTeamStop("t2", "b20");
        eqs(team(1).stops.join(","), "D8", "tm panel: removeTeamStop takes the stop off");
        ok(EP.removeTeamStop("t2", "A1").done === false, "tm panel: removing a stop not there changes nothing");
        EP.clearTeamStops("t2");
        eqs(team(1).stops.length + onDisk().trip.teams[1].stops.length, 0, "tm panel: clearTeamStops empties and saves");

        // Members: only from the party; a member no longer going is kept, flagged.
        EP.setTeamMember("t2", { id: "p-bo", name: "Bo" }, true);
        EP.setTeamMember("t2", { id: "", name: " cy " }, true);
        eqs(JSON.stringify(team(1).members), JSON.stringify([{ id: "p-bo", name: "Bo" }, { id: "", name: "Cy" }]),
            "tm panel: party members are added as the party has them");
        var rz = EP.setTeamMember("t2", { id: "p-zed", name: "Zed" }, true);
        ok(rz.done === false && rz.why.indexOf("Zed") >= 0, "tm panel: someone not going is refused, named");
        eqs(team(1).members.length, 2, "tm panel: the refused member is not added");
        ok(EP.setTeamMember("t2", { id: "p-bo", name: "Bo" }, true).done === false,
            "tm panel: a member already on the team changes nothing");
        EP.setTeamMember("t2", { id: "p-bo", name: "Bo" }, false);
        eqs(JSON.stringify(team(1).members), JSON.stringify([{ id: "", name: "Cy" }]),
            "tm panel: unticking takes a member off");
        eqs(JSON.stringify(onDisk().trip.teams[1].members), JSON.stringify(team(1).members),
            "tm panel: members are written through");
        EP.state.store.settings.trip.party = [ { id: "p-bo", name: "Bo" }, { id: "", name: "Cy" } ];
        var fl = EP.teamMemberFlags(team(0));
        eqs(fl.length + ":" + fl[0].name + ":" + fl[0].going, "1:Ana:false",
            "tm panel: a member no longer going is flagged");
        eqs(team(0).members.length, 1, "tm panel: a member no longer going is kept");
        eqs(EP.teamMemberFlags(team(1))[0].going, true, "tm panel: a going member is not flagged");
        ok(EP.setTeamMember("t1", { id: "p-ana", name: "Ana" }, false).done === true && team(0).members.length === 0,
            "tm panel: a flagged member can still be taken off");

        // Save: only teams change; everything else in the file is kept.
        open(stored());
        EP.setTeamField("t1", "goal", "New goal");
        var sv = onDisk();
        eqs(sv.packing, "old list", "tm panel: saving teams keeps settings.packing");
        eqs(JSON.stringify(sv.pace), JSON.stringify({ paceFtPerMin: 100, rig: 5 }), "tm panel: saving teams keeps pace");
        var ent = CsStationStore.parse(disk.text).store.entries;
        eqs(ent.length + ":" + ent[0].note, "1:keep me", "tm panel: saving teams keeps the entries");
        eqs(sv.trip.startDate + "|" + sv.trip.party.length + "|" + sv.trip.days.length, "2026-10-03|3|1",
            "tm panel: saving teams keeps the rest of the trip");
        eqs(sv.trip.teams[0].goal, "New goal", "tm panel: the edited team is saved");
        eqs(JSON.stringify(sv.trip.teams[1]), JSON.stringify(CsStationStore.cleanTeam(stored().trip.teams[1], 2)),
            "tm panel: saving never changes another team's data");
        var side = CsStationStore.parse(disk.text).store;
        side.entries.push({ station: "D8", note: "from Drive", status: "", team: "", who: "" });
        disk.text = CsStationStore.serialize(side);
        EP.setTeamField("t1", "goal", "Again");
        ok(disk.text.indexOf("from Drive") > 0, "tm panel: a save re-reads the file first");
        var wn = disk.writes;
        eqs(EP.saveTeams(), "", "tm panel: an unchanged save is fine");
        eqs(disk.writes, wn, "tm panel: an unchanged save writes nothing");

        // A damaged file: refuse, write nothing, keep the edit in memory.
        open(stored());
        disk.damaged = true;
        var before = disk.text;
        var dm = EP.setTeamField("t1", "name", "X");
        ok(dm.done === true && dm.why.indexOf("could not be read") >= 0,
            "tm panel: a damaged stations.json refuses the save and says so");
        eqs(disk.writes, 0, "tm panel: a damaged file is never written");
        ok(disk.text === before, "tm panel: a damaged file is left as it was");
        eqs(team(0).name, "X", "tm panel: the edit stays in memory");
        ok(EP.saveTeams().indexOf("not saved") >= 0, "tm panel: saveTeams on a damaged file says not saved");

        // An unsaved drawing keeps teams in memory and says so.
        open(stored(), "");
        var us = EP.setTeamField("t1", "name", "Y");
        ok(us.done === true && us.why.indexOf("memory") >= 0, "tm panel: an unsaved drawing keeps teams in memory and says so");
        eqs(disk.writes + ":" + team(0).name, "0:Y", "tm panel: an unsaved drawing writes nothing");

        // Same-day warnings.
        open(stored());
        eqs(EP.teamWarnings().length, 0, "tm panel: no shared person, no warning");
        EP.setTeamMember("t2", { id: "p-ana", name: "Ana" }, true);
        eqs(EP.teamWarnings().length, 0, "tm panel: the same person on different dates, no warning");
        EP.setTeamField("t2", "dayOffset", 0);
        var tw = EP.teamWarnings();
        eqs(tw.length === 1 ? tw[0].person + "|" + tw[0].date + "|" + tw[0].teams.join(",") : String(tw.length),
            "Ana|2026-10-03|Alpha,Beta", "tm panel: teamWarnings reports an overlap");

        // Build's saveTrip never wipes the teams (they are owned by saveTeams).
        open(stored());
        EP.saveTrip(CsStationStore.cleanTrip({ startDate: "2026-10-05", days: [], party: party }));
        eqs(onDisk().trip.startDate + "|" + onDisk().trip.teams.length, "2026-10-05|2",
            "tm panel: Build card's trip save keeps the stored teams");

        // The populate path loads the teams.
        open(stored());
        EP.state.teams = [];
        var realContacts = CsCalloutLocal.loadContacts;
        var realLoadPeople = EP.loadPeople;
        CsCalloutLocal.loadContacts = function() { return { topName: "", topPhone: "", escalation: "", bufferMin: "" }; };
        EP.loadPeople = function() {};
        try {
            EP.showCalloutSettings();
        } finally {
            CsCalloutLocal.loadContacts = realContacts;
            EP.loadPeople = realLoadPeople;
        }
        eqs(EP.state.teams.length, 2, "tm panel: showCalloutSettings loads the teams");
        eqs(disk.writes, 0, "tm panel: populating writes nothing");
    } finally {
        EP.state = realState;
        EP.child = realChild;
        CsStationSidecar.sidecarPath = realPath;
        CsStationSidecar.readSidecar = realRead;
        CsStationSidecar.writeSidecar = realWrite;
    }
})();

